import sys, json
Q = []
def q(topic, title, text, opts, ans, exp, stem=None):
    d = dict(topic=topic, title=title, q=text, opts=opts, ans=ans, exp=exp, pick='בחרו שתי תשובות' if len(ans) == 2 else 'בחרו תשובה אחת')
    if stem: d['stem'] = stem
    Q.append(d)
q('AI-1.1.1','אפקט ה-AI','איזו מההצהרות הבאות מספקת את הדוגמה הטובה ביותר לאפקט הבינה המלאכותית (AI Effect)?',['אנשים מאבדים את עבודתם משום שמערכות מבוססות AI מבצעות את תפקידיהם בזול וביעילות רבה יותר.','משחקי מחשב תחרותיים מאבדים פופולריות משום שמערכות מבוססות AI תמיד מנצחות.','מערכות מומחה מבוססות חוקים לאבחון רפואי אינן נחשבות עוד ל-AI.','אנשים מאמינים שבינה מלאכותית תשתלט על העולם, כפי שמוצג בסרטים.'],[2],'אפקט ה-AI = שינוי ההגדרה של AI ככל שהטכנולוגיה מתקדמת. מערכות מומחה נחשבו ל-AI בשנות ה-70–80 וכיום כבר לא.')
q('AI-1.4.1','טכנולוגיות למימוש AI','איזו מהאפשרויות הבאות אינה טכנולוגיה המשמשת למימוש בינה מלאכותית?',['מכונת וקטורים תומכים (SVM)','עץ החלטות (Decision Tree)','הסקה אבולוציונית (Evolutionary Reasoning)','אופטימיזציה בייסיאנית (Bayesian Optimization)'],[2],'אין טכנולוגיית AI בשם "הסקה אבולוציונית". SVM, עצי החלטה ואופטימיזציה בייסיאנית הם צורות של למידת מכונה.')
q('AI-1.6.1','חומרה למערכות AI','איזה מהמשפטים הבאים לגבי החומרה המשמשת למימוש מערכות מבוססות AI הוא הסביר ביותר להיות נכון?',['המעבדים לאימון מערכת המלצות במכשירים ניידים חייבים להיות זהים למעבדים שבטלפון הנייד.','יחידות עיבוד גרפי (GPU) הן בחירה סבירה למימוש מערכת ראייה ממוחשבת מבוססת AI.','מערכות למידה עמוקה חייבות להיות מאומנות, מוערכות ונבדקות באמצעות שבבים ייחודיים ל-AI.','תמיד עדיף לבחור במעבדים עם יותר ביטים כדי להשיג דיוק מספק במערכות מבוססות AI.'],[1],'GPU מתוכנן לעיבוד מקבילי של תמונות באלפי ליבות — מתאים במיוחד לרשתות עצביות לראייה ממוחשבת.')
q('AI-1.8.1','מודלים מאומנים מראש','אתה מעוניין להשתמש במודל מאומן באיכות טובה עבור מערכת לסיווג מבוסס תמונה, ושואל את הספק לגבי הנתונים ששימשו לאימון והפורמט שלהם. איזה סיכון אתה מנסה למתן באמצעות שאלות אלו?',['רמה נמוכה של דיוק הסיווג של המודלים המאומנים.','הבדלים בין הנתונים ששימשו לאימון המודל לבין הנתונים התפעוליים.','בעיות ביעילות הביצועים של המודל המאומן.','חוסר יכולת הסבר של המודל המאומן בהשוואה למודל שאימנת בעצמך.'],[1],'הסיכון המרכזי במודל מאומן מראש הוא פער בין נתוני האימון שלו לבין הנתונים בסביבת ההפעלה שלך.')
q('AI-2.1.2','דרישת אוטונומיה','איזו מההצהרות הבאות היא בסבירות הגבוהה ביותר זו שמפרטת דרישה לאוטונומיה במערכת מבוססת AI?',['המערכת תשמור על מרחק בטוח מכלי רכב אחרים עד שהנהג ילחץ על הבלם או על דוושת התאוצה.','המערכת תלמד את סגנון התגובה המועדף לאימיילים באמצעות ניטור מרחוק של תעבורת האימייל.','המערכת תשווה את התחזיות שלה למחירי בתים מול מחירי המכירה בפועל כדי לקבוע אם יש צורך באימון מחדש.','ניתן יהיה לשנות את התנהגות המערכת כדי שתעבוד עם סוגים שונים של משתמשים בפחות מיום.'],[0],'אוטונומיה = פעולה ללא התערבות אנושית עד לנקודה שבה האדם לוקח שליטה. ב׳ — למידה עצמית, ג׳ — אבולוציה, ד׳ — גמישות.')
q('AI-2.4.1','הטיה במערכות AI','איזו מההצהרות הבאות לגבי הטיה (Bias) במערכות מבוססות AI אינה נכונה?',['הטיה עשויה להיגרם על ידי משתמשים במערכת המלצות ספרים שבוחרים במכוון כדי לגרום להצעות גרועות.','הטיה עשויה להיגרם במערכת לחיזוי גיל פטירה של עובדים כאשר נתוני האימון נאספים ממטופלים שכולם פנסיונרים.','הטיה עשויה להיגרם במערכת לאמידת אשראי על ידי שימוש בנתוני אימון מבעלי כרטיסי אשראי ומשתמשים בו.','הטיה עשויה להיגרם במערכת ניווט על ידי שימוש באלגוריתם תכנון מסלול שהוא מורכב מדי להסבר למשתמשים טיפוסיים.'],[3],'מורכבות האלגוריתם פוגעת ביכולת ההסבר — לא יוצרת הטיה. שאר האפשרויות הן דוגמאות להטיית נתונים ולהרעלה.')
q('AI-2.6.1','מניפולציית תגמולים','איזו מהאפשרויות הבאות היא הסבירה ביותר לשמש כדוגמה למניפולציית תגמולים (Reward Hacking)?',['כלי עזר למתכנתים מבצע אופטימיזציה של הקוד לזמני תגובה קצרים יותר, תוך הבטחה שהדרישות הפונקציונליות מתקיימות.','מכשיר הרדמה שמטרתו לשמור על יציבות המטופלים במהלך ניתוח מספק יותר מדי מנות והמטופלים אינם מתעוררים במהירות הצפויה.','ארגון פיתוח צד שלישי שילם למתכנתי ה-AI שלו על בסיס מספר שורות הקוד שהם כותבים.','AI המשמש לשחק משחקי מחשב תחרותיים נגד בני אדם ומתמקד בהשגת הציון הגבוה ביותר.'],[1],'המכשיר "מצליח" במדד (יציבות) בדרך שאינה משקפת את הכוונה — זו מניפולציית תגמולים. ג׳ מתאר בני אדם, לא מערכת AI.')
q('AI-2.8.1','מאפיינים ובטיחות','איזו רשימת מאפיינים צפויה לגרום להכי הרבה קשיים אם המערכת תשמש כחלק ממערכת קריטית לבטיחות?',['I, IV','II, IV','II, III, V','I, III, V'],[0],'מערכת הסתברותית ולא-דטרמיניסטית היא הקשה ביותר לחיזוי ולאישור בטיחות. ניתנת להסבר ודטרמיניסטית מקלות.',stem=['I — הסתברותית','II — ניתנת להסבר','III — לא הוגנת','IV — לא דטרמיניסטית','V — דטרמיניסטית'])
q('AI-3.1.1','סיווג ורגרסיה','איזו מההצהרות הבאות מתארת בצורה הטובה ביותר סיווג (Classification) ורגרסיה (Regression) כחלק מלמידה מפוקחת?',['רגרסיה היא בדיקה שתוצאות מבחני המודל אינן משתנות כאשר אותם נתוני בדיקה מורצים.','סיווג הוא שיוך נתוני הקלט לאחת ממספר מחלקות מוגדרות מראש.','סיווג הוא תיוג הנתונים לצורך אימון מודל ה-ML.','רגרסיה היא חיזוי מספר המחלקות שמודל ה-ML מפיק.'],[1],'סיווג משייך כל קלט לאחת ממחלקות מוגדרות מראש; רגרסיה מפיקה ערך מספרי (לא "מספר מחלקות"), ותיוג אינו סיווג.')
q('AI-3.1.2','למידת חיזוק','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר דוגמה ללמידת חיזוק (Reinforcement Learning)?',['אפליקציית משחק לנייד מעדכנת את המשוב, תזמון התגובות ומספר האפשרויות שהיא מספקת בהתבסס על כמה כסף השחקנים מוציאים.','אפליקציית תרגום מחפשת באינטרנט טקסטים המוצגים במספר שפות כדי לשפר את פונקציית התרגום.','מערכת בקרת איכות במפעל משתמשת במצלמות וידאו וניתוח שמע לזיהוי פריטים פגומים על בסיס ניטור של בודק אנושי.','מערכת לניבוי תקלות ברכיבי תוכנה משתמשת במדדי איכות לזיהוי הרכיבים הצפויים להכיל הכי הרבה פגמים.'],[0],'הכסף שהשחקנים מוציאים משמש כתגמול שמכוון את פעולות האפליקציה — עקרון למידת החיזוק.')
q('AI-3.3.1','בחירת גישת ML','נתבקשת להביע דעה על גישת ה-ML למערכת שתשלוט ברמזורים בעיר חכמה כדי להבטיח זרימת תנועה קלה. איזו גישה היא הסבירה ביותר להצליח?',['למידה בלתי מפוקחת המבוססת על זיהוי אשכולות בעיר שבהם צפיפות התנועה גבוהה מהממוצע.','רגרסיה בלמידה מפוקחת המבוססת על אלפי מסעות מתויגים עם אורך ומשך המסע.','למידת חיזוק המבוססת על פונקציית תגמול המענישה פתרונות שגורמים לעומסי תנועה גבוהים יותר.','סיווג בלמידה מפוקחת המבוסס על מסלולים מועדפים שמגישים נהגים ונוסעים.'],[2],'שליטה רציפה בסביבה משתנה, שבה כל החלטה משפיעה על המצב הבא — מתאימה ללמידת חיזוק עם פונקציית תגמול.')
q('AI-3.5.1','התאמת יתר','בבדיקת מודל מאומן, המודל היה מדויק מאוד על נתוני האימות אך ביצועיו היו ירודים עם נתוני בדיקה עצמאיים. מה הסיבה הסבירה ביותר?',['תת-התאמה (Underfitting)','סטייה מושגית (Concept Drift)','התאמת יתר (Overfitting)','קריטריוני קבלה לקויים'],[2],'ביצועים מצוינים על נתונים מוכרים וירודים על נתונים חדשים = המודל אינו מכליל — Overfitting.')
q('AI-4.1.1','אתגרי נתונים','איזו מהאפשרויות הבאות היא דוגמה לאתגר שסביר להיתקל בו במהלך פיתוח ובדיקת פתרון ML?',['פעולות אנונימיזציה של נתונים דורשות בדרך כלל ידע במגוון אלגוריתמים של ML.','הנתונים עשויים להיות נתונים בלתי מובנים.','אחוז גבוה מהתקציב מושקע רק בהכנת הנתונים.','מדרגיות (Scalability) של צנרת הנתונים היא אתגר בעת אימון המודל.'],[2],'הכנת נתונים צורכת לרוב את רוב המאמץ והתקציב בפרויקט ML — אתגר מוכר.')
q('AI-4.4.1','נתונים לאימון','מדען נתונים התלונן שהמודל לא יכול להיות מאומן עם אלגוריתם מסוים, אף על פי שאלגוריתמים אחרים עובדים עם אותם נתונים. מה הסיבה הסבירה ביותר?',['נתונים שגויים','נתונים חסרים','נתונים מתויגים בצורה שגויה','נתונים בלתי מספקים'],[3],'אלגוריתמים שונים דורשים כמויות נתונים שונות — אלגוריתם מסוים (למשל רשת עמוקה) עשוי לדרוש יותר נתונים.')
q('AI-4.5.1','תיוג נכון','חברת DataSure טוענת שהמוצר שלה משפר מודלי ML באמצעות בדיקה שהנתונים תויגו כראוי. איזה ליקוי סביר ביותר שיימנע באמצעות המוצר?',['למודל יהיו נקודות תורפה בתחום האבטחה.','המודל יפיק תוצאות ברמת דיוק נמוכה.','המודל לא ימלא את הפונקציה המיועדת לו.','המודל יפיק פלטים מוטים.'],[1],'תיוג שגוי מלמד את המודל דפוסים שגויים ומוביל לדיוק נמוך.')
q('AI-4.5.2','גישות תיוג','לאחר שמצא שנתוני האימון אינם מספיקים, מהנדס ML התחיל לסובב תמונות מתויגות כדי ליצור נתוני אימון נוספים. איזו גישת תיוג מיושמת?',['מיקור המונים (Crowdsourcing)','הגדלה (Augmentation)','תיוג מבוסס AI','מיקור חוץ (Outsourcing)'],[1],'יצירת דוגמאות חדשות מדוגמאות מתויגות קיימות (סיבוב, היפוך) = Data Augmentation.')
q('AI-5.1.1','Precision ממטריצת בלבול','איזו מהאפשרויות הבאות מייצגת את הדיוק (Precision) של המסווג?',['20/120 × 100','78/120 × 100','78/100 × 100','22/100 × 100'],[2],'Precision = TP / (TP + FP) = 78 / (78 + 22) = 78/100.',stem=['חזוי חיובי: בפועל חיובי = 78 (TP), בפועל שלילי = 22 (FP)','חזוי שלילי: בפועל חיובי = 6 (FN), בפועל שלילי = 14 (TN)'])
q('AI-5.4.1','מדד לרגרסיה','מודל ML שאומן על נתוני עבר עם פלט מתויג קובע כמה חשמל לייצר בזמן נתון ביום. איזה מדד סביר ביותר שישמש לקביעת איכות המודל?',['מקדם ההסבר (R-squared)','דיוק (Precision)','שליפה / כיסוי (Recall)','חיוביים שגויים (False Positives)'],[0],'כמות חשמל היא ערך מספרי רציף — בעיית רגרסיה, ולכן R² מתאים. שאר המדדים לסיווג.')
q('AI-5.4.2','בחירת מדד','אפליקציה קובעת אם חיית מחמד רעבה. ידוע שהכלב אינו רעב רוב הזמן. אבחון שגוי של הכלב כרעב עלול להוביל להאכלת יתר ולבעיות בריאות. איזה מדד תבחר?',['נכונות (Accuracy)','רמת דיוק (Precision)','רגישות (Recall)','ציון F1'],[1],'הטעות היקרה היא FP (רעב כשלא) — לכן Precision. Accuracy מטעה בנתונים לא מאוזנים.')
q('AI-6.1.1','רשת עצבית עמוקה','איזו מהאפשרויות הבאות מתארת בצורה הטובה ביותר רשת עצבית עמוקה (Deep Neural Network)?',['מבנה היררכי של נוירונים, שבו הנוירונים העמוקים ביותר מקבלים את רוב ההחלטות.','נוירונים מחוברים, כאשר לכל נוירון יש הטיה (Bias) ולכל חיבור יש משקל (Weight).','מספר שכבות, שבו כל שכבה (למעט קלט ופלט) מחוברת לכל שכבה אחרת, ושגיאות מופצות לאחור.','שכבות נוירונים שכל אחד מייצר ערך הפעלה בהתבסס על נוירונים אחרים באותה שכבה.'],[1],'לכל נוירון Bias ולכל חיבור Weight. שכבות מחוברות רק לשכבה הסמוכה, וההפעלה מבוססת על השכבה הקודמת.')
q('AI-6.2.1','מדדי כיסוי','איזו מההצהרות הבאות מתארת נכון מדד כיסוי לבדיקת רשתות עצביות?',['כיסוי שינוי ערך מבוסס על נוירונים בודדים שנראים כמשפיעים על הפלט הכולל.','כיסוי סף מבוסס על נוירונים שמוציאים ערך הפעלה גדול מערך קבוע מראש בין אפס לאחד.','כיסוי נוירונים מודד את החלק היחסי של הנוירונים שמופעלים בכל רגע במהלך הבדיקה.','כיסוי שינוי סימן מודד נוירונים שמוציאים ערכים חיוביים, שליליים ואפס.'],[1],'Threshold Coverage = הפעלה מעל סף קבוע מראש. כיסוי נוירונים נמדד לאורך כל הבדיקות, לא "בכל רגע".')
q('AI-7.1.1','אתגר בבדיקות','איזו מהדרישות הבאות עבור מערכת מבוססת AI סביר ביותר שתגרום לאתגר משמעותי בבדיקות?',['המערכת תהיה מדויקת יותר מהמערכת שהיא מחליפה.','רכיב ה-AI יהיה בעל דיוק של 100%.','מפעיל אנושי יוכל לעקוף את המערכת בתוך שנייה אחת.','המערכת תחקה את הרגשות האנושיים של שחקן משחק טיפוסי.'],[3],'חיקוי התנהגות ורגשות אנושיים קשה לאפיון ולהגדרת Oracle — אתגר בדיקה משמעותי.')
q('AI-7.2.1','נתוני בדיקה','איזה מהגורמים הבאים הקשורים לנתוני בדיקה עלול להקשות על בדיקת מערכות מבוססות AI?',['השגת ביג דאטה בעל מהירות גבוהה (High Velocity)','השגת נתונים ממקור יחיד','השגת נתונים בנפרד ממדעני הנתונים','השגת נתונים מאתרי אינטרנט ציבוריים'],[0],'נתונים בנפח ובקצב גבוהים קשים להשגה, לאחסון ולעיבוד לצורכי בדיקה.')
q('AI-7.4.1','החלטות אנושיות','מדוע יש להתחשב בדיוק ההחלטות של בני אדם בבדיקות, בנוסף לדיוק ההחלטות של מערכות AI?',['החלטות אינטואיטיביות של בני אדם יכולות להתקבל מהר יותר במצבים מסוימים.','החלטות לא אתיות יכולות להתקבל הן על ידי בני אדם והן על ידי מערכות AI.','דיוק החלטות אנושיות אינו רלוונטי לבדיקת מערכות AI.','החלטות אנושיות עשויות להיות באיכות נמוכה יותר כאשר הן ניתנות בעקבות המלצה של מערכת AI.'],[3],'Automation Bias — אנשים נוטים לסמוך על המלצת המערכת, ואיכות החלטתם עלולה לרדת.')
q('AI-7.2.2','בדיקות ברמת מערכת','מערכת גביית אגרה מבוססת ML מסווגת כלי רכב מתמונות ממצלמות שונות ברזולוציות שונות (JPEG 320×480). המודל צריך לסווג בדיוק גבוה מוגדר ולהיבדק נגד פגיעויות. כל תחנה עצמאית. אילו סוגי בדיקות מתאימים ביותר ברמת מערכת?',['בדיקות לסטייה מושגית (Concept Drift)','בדיקות עוינות (Adversarial Testing)','בדיקות מדרגיות (Scalability)','בדיקות הוגנות (Fairness)','בדיקות צנרת נתונים (Data Pipeline)'],[1,4],'נדרשת בדיקה נגד פגיעויות (Adversarial) ובדיקת צנרת הנתונים — המרת תמונות ממצלמות ורזולוציות שונות לפורמט הנדרש.')
q('AI-8.1.1','מערכת לומדת-עצמית','איזו מההצהרות הבאות מתארת בצורה הטובה ביותר אתגר בדיקה ספציפי למערכת לומדת-עצמית?',['המערכת דורשת אימון מחדש באופן קבוע ולכן בדיקות קבועות.','המערכת משוחררת באופן תדיר ולכן נדרשות בדיקות רגרסיה.','המערכת משתנה כך שבדיקות שעברו בעבר עלולות להיכשל.','המערכת דורשת מפעיל אנושי שנדרש גם עבור הבדיקות.'],[2],'מערכת לומדת-עצמית משנה את התנהגותה בעצמה — בדיקות שעברו עלולות להיכשל (שינוי בלתי צפוי).')
q('AI-8.3.1','בדיקת הטיה','איזו מהאפשרויות הבאות לא סביר שתידרש לצורך בדיקת מערכת להטיה?',['שיתוף משתמשים נבחרים שידוע כי הם מוטים.','מדידת ההשפעה של שינויים בקלטי הבדיקה על פלטי הבדיקה.','תצפית על האופן שבו פלטים בייצור מתואמים עם קלטי הייצור.','השגת נתונים נוספים ממקורות אחרים.'],[0],'שיתוף משתמשים מוטים אינו טכניקה לבדיקת הטיה. השוואת קלטים ופלטים ונתונים נוספים הם חלק מהבדיקה.')
q('AI-8.5.1','מורכבות מערכת','איזו מההצהרות הבאות מתארת בצורה הטובה ביותר כיצד מורכבות מערכת יוצרת אתגרים בבדיקת מערכת AI?',['בדיקות להטיה עשויות לדרוש נתונים שאינם בידי הצוות.','יצירה ידנית של בדיקות קופסה לבנה עשויה להיות קשה.','קביעת האתיות של המערכת עשויה להיות סובייקטיבית.','יכול להיות קשה למצוא נתונים מייצגים לאימון מודל.'],[1],'מורכבות המודל (אלפי נוירונים ומשקלים) מקשה מאוד על תכנון ידני של בדיקות White-Box.')
q('AI-8.2.1','מאפיינים לקריטריוני קבלה','משרד הבריאות משתמש במערכת AI לזיהוי קבוצות פגיעות של מטופלים. התוצאות משותפות גם עם סוכנויות ממשלתיות וחברות ביטוח. המערכת אומנה על סקרים של 5,000 גברים מעל 50 ו-25,000 נשים מעל 30, ותמשיך ללמוד מרשתות חברתיות ציבוריות. אילו מאפיינים יש לשקול בזהירות הרבה ביותר?',['הסתגלותיות (Adaptability)','הטיה (Bias)','יכולת הסבר (Explainability)','גמישות (Flexibility)','אוטונומיה (Autonomy)'],[1,2],'המדגם אינו מאוזן (הטיה), וההחלטות משפיעות על אנשים ומשותפות עם גורמים חיצוניים — נדרשת יכולת הסבר.')
q('AI-9.1.1','בדיקות עוינות','מהנדס ML מחפש קלטים שניתן לנצל ולאחר מכן משתמש בהם כדי לאמן מחדש את המודלים כך שיהיו חסינים מולם. איזו גישה הוא מיישם?',['ולידציה (Validation)','בדיקות עוינות (Adversarial Testing)','בדיקות צנרת נתונים (Data Pipeline)','בדיקות מדרגיות (Scalability)'],[1],'איתור דוגמאות עוינות ואימון מחדש איתן לחיזוק העמידות = Adversarial Testing.')
q('AI-9.3.1','Pairwise Testing','יש לבדוק שבעה תפקודי רכב אוטונומי (VF) בתנאי סביבה רבים (מעל 50, EC). איזו טכניקה סבירה ביותר לבדיקת מגוון התפקודים בתנאים שונים?',['בדיקות A/B המבוססות על פרמטרי VF ו-EC','בדיקות שילוב של כל פרמטרי VF ו-EC','בדיקות זוגיות (Pairwise) של הערכים הרלוונטיים של VF ו-EC','בדיקות גב אל גב של ערכי VF ו-EC רלוונטיים'],[2],'מספר עצום של פרמטרים — Pairwise מכסה כל זוג ערכים במינימום בדיקות; שילוב מלא אינו מעשי.')
q('AI-9.4.1','פסאודו-אורקל','מנהל בדיקות בונה מערכת שאינה מבוססת AI עם פונקציונליות דומה למערכת ה-AI הנבדקת, כדי לתמוך בבדיקות מערכת. איזה משפט הוא הנכון בסבירות הגבוהה ביותר?',['נבחרו בדיקות גב אל גב כיוון שהן מסייעות לפתור את בעיית האורקל באמצעות פסאודו-אורקל.','נבחרו בדיקות A/B כיוון שהן מסייעות לפתור את בעיית האורקל באמצעות פסאודו-אורקל.','נבחרו בדיקות גב אל גב כיוון שניתן לאמת את הדרישות הלא-פונקציונליות מול הפסאודו-אורקל.','נבחרו בדיקות A/B כיוון שניתן לאמת את הדרישות הלא-פונקציונליות מול הפסאודו-אורקל.'],[0],'מערכת חלופית עם פונקציונליות דומה משמשת פסאודו-אורקל ב-Back-to-Back Testing — משווים את הפלטים.')
q('AI-9.5.1','בדיקות מטמורפיות','מערכת חיפוש AI ממליצה על טלפונים לפי טווח מחיר, מצלמה 3D, גודל מסך, מערכת הפעלה וחיי סוללה. במקרה המקור "מצלמה 3D = לא חשוב" והפלט: SnapHappy_X1, SnapHappy_M2, SnapHappy_M3, ClickNow_1000x, ClickNow_1000xs. במקרה נגזר ק1 "מצלמה 3D = כן", ובק2 "מצלמה 3D = לא" (שאר הקלטים זהים). איזו רשימה סבירה ביותר להיות תקפה?',['ק1: SnapHappy_X1, SnapHappy_M2 · ק2: ClickNow_1000x, ClickNow_1000xs','ק1: SnapHappy_M2, SnapHappy_M3, ClickNow_1000xs · ק2: SnapHappy_X1, ClickNow_1000x','ק1: כל חמשת הטלפונים · ק2: SnapHappy_X1, SnapHappy_M2, SnapHappy_M3','ק1: כל חמשת הטלפונים · ק2: כל חמשת הטלפונים'],[1],'היחס המטמורפי: "כן" ו"לא" מחלקים את תוצאת "לא חשוב" — שתי הרשימות זרות ואיחודן שווה לרשימת המקור.')
q('AI-9.6.1','בדיקות חוקרות','בתכנון בדיקות מערכת ל-AI הוצע להשתמש בבדיקות חוקרות (Exploratory Testing) בנוסף לבדיקות מתוסרטות. איזה תרחיש הוא דוגמה לבדיקות חוקרות?',['נתוני האימון מוצגים בכלי ויזואליזציה לבחינת היבטים שונים של הנתונים.','בדיקות שנכתבו בטכניקת מחלקות שקילות במחזור הקודם מורצות.','נעשה שימוש ברשימת הבדיקות של Google ל-ML.','מחושבים מדדי ביצועים פונקציונליים של ML.'],[0],'חקירת הנתונים בכלי ויזואליזציה (Exploratory Data Analysis) היא דוגמה לבדיקה חוקרת במערכות AI.')
q('AI-9.7.1','בחירת טכניקות','מוצר AI לחילוץ פסקי דין רלוונטיים משמש שופטים. המערכת צריכה להיות חסינה לקלטים זדוניים, קיים מוצר קוד פתוח דומה, וחסר אורקל בדיקה. אילו טכניקות יש לבחור לבדיקות מערכת?',['בדיקות A/B','בדיקות גב אל גב (Back-to-Back)','בדיקות עוינות (Adversarial)','בדיקות מעברי מצבים (State Transition)','חישוב מדדי ביצועים פונקציונליים של ML'],[1,2],'המוצר הדומה משמש פסאודו-אורקל (Back-to-Back), והחסינות לקלטים זדוניים נבדקת ב-Adversarial Testing.')
q('AI-10.1.1','סביבת בדיקות','איזה מהמשפטים הבאים הוא דוגמה להבדל בין סביבת בדיקות למערכות AI לסביבת בדיקות למערכות קונבנציונליות?',['סביבת בדיקות ל-AI עשויה לדרוש מנגנון לקביעת האופן שבו התקבלה החלטה מסוימת.','סביבת בדיקות ל-AI זקוקה לסימולטורים, בעוד שמערכות קונבנציונליות אינן זקוקות לכך.','סביבת בדיקות ל-AI זקוקה לכמויות גדולות של נתונים, בעוד שקונבנציונליות אינן זקוקות לכך.','סביבות בדיקות ל-AI נדרשות ל-GPU, בעוד שקונבנציונליות אינן זקוקות לכך.'],[0],'הצורך בהסבר החלטות (Explainability) ייחודי ל-AI. סימולטורים, נתונים ו-GPU נדרשים לעיתים גם במערכות קונבנציונליות.')
q('AI-11.1.1','AI לסיווג תקלות','באיזה תרחיש שימוש ב-AI יהיה מועיל ביותר בעת סיווג תקלות חדשות?',['מספר קטן של תקלות דורש סיווג באפליקציה חדשה.','מספר גדול של תקלות מדווח באפליקציה קטנה.','נתונים מינימליים מדווחים בדוחות תקלות טיפוסיים.','צוות פיתוח חדש צריך לדעת מיהו המפתח המתאים ביותר לתיקון תקלה.'],[1],'AI מועיל כשיש כמות גדולה של תקלות לסיווג — ויש מספיק נתונים ללמידה.')
q('AI-11.2.1','בסיס ליצירת בדיקות','איזה מהבאים הוא הכלי שמערכת AI תשתמש בו בסבירות הגבוהה ביותר כבסיס ליצירת מקרי בדיקה פונקציונליים?',['אמנת בדיקות (Test Charter)','תרשים זרימה של המערכת','לוגים של שרת אינטרנט','דוחות קריסה'],[2],'לפי התשובון: לוגים של שרת מתעדים שימוש אמיתי במערכת, ו-AI יכול לגזור מהם מקרי בדיקה פונקציונליים.')
q('AI-11.3.1','אופטימיזציה של רגרסיה','כיצד כלי מבוסס AI יכול לבצע אופטימיזציה של בדיקות רגרסיה?',['על ידי ניתוח תוצאות בדיקה חיוביות שגויות (False Positives)','על ידי ניתוח מידע מפעילויות בדיקה קודמות','על ידי שימוש באלגוריתמים גנטיים ליצירת מקרי בדיקה חדשים','על ידי עדכון התוצאות הצפויות כדי להתמודד עם Concept Drift'],[1],'ניתוח היסטוריית הבדיקות מאפשר לבחור ולתעדף את מקרי הרגרסיה הרלוונטיים ביותר.')
q('AI-11.4.1','חיזוי תקלות','כיצד כלי מבוסס AI יכול לבצע חיזוי תקלות (Defect Prediction)?',['על ידי שימוש בשפה טבעית לשאול מפתחים היכן הם צופים שיתרחשו תקלות','על ידי ניתוח גורמי תקלות שעלו בקוד בסיס דומה','על ידי ניתוח תקלות חיוביות שגויות (False Positives)','על ידי סריקת קוד לזיהוי תקלות באמצעות חוקים'],[1],'חיזוי תקלות מבוסס על למידה ממאפייני קוד ותקלות היסטוריות בקוד דומה.')
assert len(Q) == 40
L=[{"L":"cover","tag":"CT-AI · מבחן לדוגמא | Sample Exam","t":"מבחן לדוגמא","en":"ISTQB® CT-AI — Certified Tester AI Testing","objh":"מבנה המבחן","obj":["40 שאלות — לכל שאלה שקף שאלה ושקף תשובה","חלק מהשאלות דורשות בחירת שתי תשובות","נסו לענות לפני מעבר לשקף התשובה","בשקף התשובה מופיעים מטרת הלימוד והסבר קצר","מבוסס על מבחן הדוגמה הרשמי בתרגום ITCB"],"k":""}]
for n,x in enumerate(Q,1):
    base={"L":"mcq","k":f"שאלה {n} · {x['topic']}","t":f"שאלה {n} — {x['title']}","q":x['q'],"opts":x['opts'],"pick":x['pick']}
    if x.get('stem'): base['stem']=x['stem']
    L.append(dict(base)); a=dict(base); a['ans']=x['ans']; a['exp']=x['exp']; a['t']=f"שאלה {n} — תשובה"; L.append(a)
